/** Upstream ..._build_summary_prompt, the iterative-update form. */
export function iterativePromptText(
  preamble: string,
  boundedPreviousSummary: string,
  contentToSummarize: string,
  memorySection: string,
  templateSections: string,
): string {
  return preamble +
    "\n\nYou are updating a context compaction summary. A previous compaction produced the summary below. New conversation turns have occurred since then and need to be incorporated.\n\nPREVIOUS SUMMARY:\n" +
    boundedPreviousSummary +
    "\n\nNEW TURNS TO INCORPORATE:\n" +
    contentToSummarize +
    memorySection +
    "\n\nUpdate the summary using this exact structure. PRESERVE all existing information that is still relevant. ADD new completed actions to the numbered list (continue numbering). Move items from \"In Progress\" to \"Completed Actions\" when done. Move answered questions to \"Resolved Questions\". Update \"Active State\" to reflect current state. Remove information only if it is clearly obsolete. CRITICAL: Update \"" +
    HISTORICAL_TASK_HEADING +
    "\" to reflect the user's most recent unfulfilled input — this includes any question, decision request, or discussion turn that the assistant has not yet answered. Only write \"None\" if the last exchange was fully resolved.\n\n" +
    templateSections;
}

/** Upstream ..._build_summary_prompt, the first-summary form. */
export function freshPromptText(
  preamble: string,
  contentToSummarize: string,
  memorySection: string,
  templateSections: string,
): string {
  return preamble +
    "\n\nCreate a structured checkpoint summary for the conversation after earlier turns are compacted. The summary should preserve enough detail for continuity without re-reading the original turns.\n\nTURNS TO SUMMARIZE:\n" +
    contentToSummarize +
    memorySection +
    "\n\nUse this exact structure:\n\n" +
    templateSections;
}

/** Upstream ..._build_summary_prompt, the focus-topic addition. */
