/** Upstream ContextCompressor._temporal_anchoring_rule. "" when the date is unknown. */
export function temporalAnchoringText(todayStr: string): string {
  if (!todayStr) return "";
  return "\nTEMPORAL ANCHORING: The current date is " +
    todayStr +
    ". When an action has already been carried out, phrase it as a completed, dated, past-tense fact rather than an open instruction. For example, rewrite \"email John about the proposal\" as \"Sent the proposal email to John on " +
    todayStr +
    ".\" Never leave a finished action worded as if it still needs doing, and never invent a date for work that has not happened yet.\n";
}
